  "İlan yükleniyor...": { de: "Anzeige wird geladen...", fr: "Chargement de l’annonce...", en: "Loading listing...", ar: "جارٍ تحميل الإعلان...", fa: "در حال بارگذاری آگهی...", ru: "Загрузка объявления..." },
  "Videoyu izle": { de: "Video ansehen", fr: "Voir la vidéo", en: "Watch video", ar: "مشاهدة الفيديو", fa: "تماشای ویدیو", ru: "Смотреть видео" },
