  "Yönetici hesabını etkinleştir": { de: "Administratorkonto aktivieren", fr: "Activer le compte administrateur", en: "Activate admin account", ar: "تفعيل حساب المسؤول", fa: "فعال‌سازی حساب مدیر", ru: "Активировать аккаунт администратора" },
