  "Belgeyi ve hesabı onayla": { de: "Dokument und Konto freigeben", fr: "Valider le document et le compte", en: "Approve document and account", ar: "الموافقة على الوثيقة والحساب", fa: "تأیید مدرک و حساب", ru: "Одобрить документ и аккаунт" },
