  "Mahalle bulunamadı veya birden fazla eşleşti: {name}": { de: "Stadtviertel nicht gefunden oder mehrdeutig: {name}", fr: "Quartier introuvable ou ambigu : {name}", en: "Neighbourhood not found or matched more than once: {name}", ar: "لم يتم العثور على الحي أو تطابق أكثر من مرة: {name}", fa: "محله پیدا نشد یا بیش از یک مورد مطابقت داشت: {name}", ru: "Район не найден или найдено несколько совпадений: {name}" },
