  "{n} talep": { de: "{n} Anfragen", fr: "{n} demandes", en: "{n} requests", ar: "{n} طلب", fa: "{n} درخواست", ru: "Заявок: {n}" },
  "{n} yeni": { de: "{n} neu", fr: "{n} nouvelles", en: "{n} new", ar: "{n} جديد", fa: "{n} جدید", ru: "новых: {n}" },
