  "Proje hakkında": { de: "Über das Projekt", fr: "À propos du programme", en: "About the project", ar: "عن المشروع", fa: "درباره پروژه", ru: "О проекте" },
  "Konut tipleri": { de: "Wohnungstypen", fr: "Types de logements", en: "Unit types", ar: "أنواع الوحدات", fa: "انواع واحد", ru: "Типы квартир" },
