  "Konut tipini kaldır": { de: "Wohnungstyp entfernen", fr: "Supprimer ce type de logement", en: "Remove unit type", ar: "إزالة نوع الوحدة", fa: "حذف نوع واحد", ru: "Удалить тип квартиры" },
